SourceCode.Declaration:
/// <summary>
/// Extension class for InventSeqNum to handle fixed batch number generation
/// </summary>
[ExtensionOf(classStr(InventSeqNum))]
internal final class AVA_InventSeqNumBatch_Extension
{
}

Method.Source:
/// <summary>
/// Returns batch number - either fixed batch or generated from number sequence
/// </summary>
/// <returns>Batch number</returns>
public InventBatchId getBatchNum()
{
    InventBatchId batchId;
    InventNumGroup inventNumGroup;

    // Get the tracking number group
    if (this.parmNumberSeqModuleBatch() && this.parmNumberSeqModuleBatch().parmNumberSeqGroup())
    {
        select firstonly AVA_FixedBatch, AVA_FixedBatchNumber from inventNumGroup
            where inventNumGroup.NumberSeqGroupId == this.parmNumberSeqModuleBatch().parmNumberSeqGroup();

        // If fixed batch is enabled, return the fixed batch number
        if (inventNumGroup.AVA_FixedBatch == NoYes::Yes && inventNumGroup.AVA_FixedBatchNumber)
        {
            batchId = inventNumGroup.AVA_FixedBatchNumber;
            return batchId;
        }
    }

    // Otherwise, use standard number sequence logic
    batchId = next getBatchNum();

    return batchId;
}
